from typing import List
import collections

class Solution:
    def countCornerRectangles(self, grid: List[List[int]]) -> int:
        count = collections.defaultdict(int)
        ans = 0
        for row in grid:
            cols = [c for c, val in enumerate(row) if val == 1]
            for i in range(len(cols)):
                for j in range(i + 1, len(cols)):
                    pair = (cols[i], cols[j])
                    ans += count[pair]
                    count[pair] += 1
        return ans

class Solution {
public:
    int countCornerRectangles(vector<vector<int>>& grid) {
        int ans = 0;
        int n = grid[0].size();
        vector<vector<int>> count(n, vector<int>(n, 0));
        for (auto& row : grid) {
            vector<int> cols;
            for (int c = 0; c < n; c++) {
                if (row[c] == 1) cols.push_back(c);
            }
            for (int i = 0; i < cols.size(); i++) {
                for (int j = i + 1; j < cols.size(); j++) {
                    int c1 = cols[i], c2 = cols[j];
                    ans += count[c1][c2];
                    count[c1][c2]++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countCornerRectangles(int[][] grid) {
        int ans = 0;
        int n = grid[0].length;
        int[][] count = new int[n][n];
        for (int[] row : grid) {
            List<Integer> cols = new ArrayList<>();
            for (int c = 0; c < n; c++) {
                if (row[c] == 1) cols.add(c);
            }
            for (int i = 0; i < cols.size(); i++) {
                for (int j = i + 1; j < cols.size(); j++) {
                    int c1 = cols.get(i), c2 = cols.get(j);
                    ans += count[c1][c2];
                    count[c1][c2]++;
                }
            }
        }
        return ans;
    }
}

var countCornerRectangles = function(grid) {
    let ans = 0;
    const n = grid[0].length;
    const count = Array.from({ length: n }, () => new Array(n).fill(0));
    for (const row of grid) {
        const cols = [];
        for (let c = 0; c < n; c++) {
            if (row[c] === 1) cols.push(c);
        }
        for (let i = 0; i < cols.length; i++) {
            for (let j = i + 1; j < cols.length; j++) {
                const c1 = cols[i], c2 = cols[j];
                ans += count[c1][c2];
                count[c1][c2]++;
            }
        }
    }
    return ans;
};
